(()=>{'use strict';const key='buchee_aurora_intro_seen_v4';const slides=[{image:'https://images.unsplash.com/photo-1452587925148-ce544e77e70d?auto=format&fit=crop&w=1200&q=88',title:'Paylaş, Üret, <em>Her Yerde Görün.</em>',text:'Buchee’de hem kısa videolar (reels) hem de gönderiler (post) paylaşabilir, düşüncelerini anlık olarak yazılarla (twit) ifade edebilirsin.',features:[['reels','Reels<br>Paylaş'],['post','Post<br>Paylaş'],['twit','Twit<br>At']]},{image:'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=88',title:'İçerik Üret,<br>Kazanç Elde Et.',text:'Nitelikli içerikler paylaş, etkileşim kazan ve platformun sunduğu kazanç fırsatlarından yararlan.',features:[['coins','Etkileşimle<br>Kazan'],['award','Ödüller<br>Topla'],['gift','Özel<br>Avantajlar']]},{image:'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=88',title:'Yerli ve Bağımsız<br>Bir Platform.',text:'Buchee, Türkiye’de geliştirilen, özgür, güvenli ve kullanıcı odaklı bir sosyal medya platformudur.',features:[['shield','Güvenli'],['bolt','Hızlı'],['infinity','Sınırsız<br>Erişim']]}];let step=0,shown=false;const root=document.createElement('section');root.id='buchee-aurora-intro';root.hidden=true;root.setAttribute('aria-label','Buchee tanıtımı');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');function render(){const x=slides[step];const icons={reels:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M8 3l4 6m3-6 4 6"/><path d="m10 12 5 3-5 3z"/>',post:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m4 18 6-6 4 4 3-3 4 4"/>',twit:'<rect x="3" y="4" width="18" height="15" rx="3"/><path d="M7 9h10M7 13h7"/>',coins:'<ellipse cx="12" cy="6" rx="7" ry="3"/><path d="M5 6v5c0 4 14 4 14 0V6M5 11v5c0 4 14 4 14 0v-5"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m9 14-2 8 5-3 5 3-2-8M12 6l1 2 2 .4-1.5 1.5.4 2-1.9-1-2 1 .4-2L9 8.4l2-.4z"/>',gift:'<rect x="3" y="10" width="18" height="11" rx="1"/><path d="M2 7h20v4H2zM12 7v14M12 7C7 7 6 3 9 3c2 0 3 4 3 4Zm0 0s1-4 3-4c3 0 2 4-3 4Z"/>',shield:'<path d="M12 2 4 5v6c0 6 4 9 8 11 4-2 8-5 8-11V5z"/><path d="m8 12 3 3 5-6"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',infinity:'<path d="M12 12C8 4 2 6 2 12s6 8 10 0c4-8 10-6 10 0s-6 8-10 0z"/>'};root.innerHTML='<div class="buchee-reference-screen buchee-reference-'+step+'"><div class="buchee-reference-image" style="background-image:linear-gradient(180deg,rgba(0,0,0,.10) 0%,rgba(0,0,0,.02) 26%,rgba(0,0,0,.70) 51%,#08090b 72%),url(&quot;'+x.image+'&quot;)"></div><div class="buchee-reference-top"><div class="buchee-reference-brand">Buchee</div><button type="button" data-intro="skip" class="buchee-reference-skip">Atla</button></div>'+(step===2?'<div class="buchee-turkish-flag" aria-label="Türk bayrağı"><svg viewBox="0 0 300 200" role="img" aria-label="Türk bayrağı"><rect width="300" height="200" fill="#e30a17"/><circle cx="128" cy="100" r="55" fill="#fff"/><circle cx="146" cy="100" r="44" fill="#e30a17"/><polygon points="197,75 202,91 219,91 205,102 211,119 197,109 183,119 188,102 174,91 191,91" fill="#fff"/></svg></div>':'')+'<div class="buchee-reference-content">'+(step===2?'<span class="buchee-reference-turkish"><span>🇹🇷</span> Türkiye’de Geliştirildi</span>':'')+'<h1>'+x.title+'</h1><p>'+x.text+'</p><div class="buchee-reference-features">'+x.features.map(f=>'<div class="buchee-reference-feature"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+icons[f[0]]+'</svg><span>'+f[1]+'</span></div>').join('')+'</div></div><div class="buchee-reference-footer"><div class="buchee-reference-footer-left">'+(step>0?'<button type="button" class="buchee-reference-back" data-intro="back" aria-label="Önceki ekran">←</button>':'')+'<div class="buchee-reference-dots">'+slides.map((_,i)=>'<span class="'+(i===step?'active':'')+'"></span>').join('')+'</div></div><button type="button" class="buchee-reference-next" data-intro="next">'+(step===2?'Hemen Başla':'')+'<span aria-hidden="true">→</span></button></div></div>'}function close(mode){root.hidden=true;document.body.classList.remove('buchee-intro-locked');document.documentElement.classList.remove('buchee-intro-locked');document.body.style.removeProperty('overflow');try{localStorage.setItem(key,'1')}catch{}if(mode){const b=document.querySelector('#auth-root [data-auth="'+mode+'"]');if(b)b.click()}}root.addEventListener('click',e=>{const a=e.target.closest('[data-intro]');if(!a)return;const v=a.dataset.intro;if(v==='back'&&step>0){step--;render()}else if(v==='next'&&step<slides.length-1){step++;render()}else close(v==='login'?'login':v==='next'?'signup':null)});let touchStartX=0,touchStartY=0,touchStartAt=0;root.addEventListener('touchstart',e=>{if(root.hidden||!e.touches.length)return;touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;touchStartAt=Date.now()},{passive:true});root.addEventListener('touchend',e=>{if(root.hidden||!e.changedTouches.length||!touchStartAt)return;const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY;touchStartAt=0;if(Math.abs(dx)<65||Math.abs(dx)<Math.abs(dy)*1.4)return;if(dx<0&&step<slides.length-1){step++;render()}else if(dx>0&&step>0){step--;render()}},{passive:true});function check(){if(shown||!root.hidden)return;const auth=document.getElementById('auth-root'),app=document.getElementById('app-root');if(!auth||!app||auth.classList.contains('hidden')||!app.classList.contains('hidden')||!auth.querySelector('#auth-form'))return;let seen=false;try{seen=localStorage.getItem(key)==='1'}catch{}if(seen)return;shown=true;step=0;render();root.hidden=false;document.body.classList.add('buchee-intro-locked');document.documentElement.classList.add('buchee-intro-locked');document.body.style.overflow='hidden'}function init(){document.body.append(root);const auth=document.getElementById('auth-root');if(auth){new MutationObserver(()=>{if(!root.hidden&&auth.classList.contains('hidden'))close();else check()}).observe(auth,{attributes:true,attributeFilter:['class'],childList:true,subtree:false})}check();setTimeout(check,600);setTimeout(check,1800)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();